package tmmodern;
import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.effect.*;import net.minecraft.network.chat.Component;
/** Charge/target/damage are derived on the server, unlike the old client-supplied damage packet. */
public class KatanaItem extends Item implements thaumcraft.api.IWarpingGear,tc4revival.content.RepairableItem {
    public final int material;public KatanaItem(int material){super(new Properties().stacksTo(1).rarity(Rarity.UNCOMMON));this.material=material;}
    public static net.minecraft.world.damagesource.DamageSource source(Player p,ItemStack s){if(!s.hasTag()||!s.getTag().contains("inscription"))return p.damageSources().playerAttack(p);String id=s.getTag().getInt("inscription")==0?"katana_fire":"katana_magic";return new net.minecraft.world.damagesource.DamageSource(p.level().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,net.minecraft.resources.ResourceLocation.parse("taintedmagic:"+id))),p);}
    /** The original charged-strike packet bypassed armor and did not apply ordinary inscription hit effects. */
    public static net.minecraft.world.damagesource.DamageSource chargedSource(Player player){
        var type=player.level().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE)
            .getHolderOrThrow(net.minecraft.world.damagesource.DamageTypes.PLAYER_ATTACK);
        return new net.minecraft.world.damagesource.DamageSource(type,player){
            @Override public boolean is(net.minecraft.tags.TagKey<net.minecraft.world.damagesource.DamageType> tag){
                return tag.equals(net.minecraft.tags.DamageTypeTags.BYPASSES_ARMOR)||super.is(tag);
            }
        };
    }
    public float damage(){return new float[]{14.25f,17.5f,20.75f}[material];}
    @Override public int getWarp(ItemStack s,Player p){return new int[]{0,3,7}[material];}
    @Override public com.google.common.collect.Multimap<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier> getAttributeModifiers(EquipmentSlot slot,ItemStack s){var out=com.google.common.collect.HashMultimap.<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier>create();if(slot==EquipmentSlot.MAINHAND)out.put(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_SPEED,new net.minecraft.world.entity.ai.attributes.AttributeModifier(BASE_ATTACK_SPEED_UUID,"Weapon modifier",-2.4,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));if(slot==EquipmentSlot.MAINHAND)out.put(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE,new net.minecraft.world.entity.ai.attributes.AttributeModifier(BASE_ATTACK_DAMAGE_UUID,"Katana damage",damage()-1,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));return out;}
    @Override public boolean hurtEnemy(ItemStack s,LivingEntity target,LivingEntity owner){if(material>0)target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,60));if(material==2)target.addEffect(new MobEffectInstance(MobEffects.HUNGER,120));if(s.hasTag()&&s.getTag().contains("inscription")){switch(s.getTag().getInt("inscription")){case 0->target.setSecondsOnFire(3);case 1->target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,140));case 2->target.addEffect(new MobEffectInstance(MobEffects.WITHER,60));}}TMRuntime.sound(owner.level(),owner.blockPosition(),"thaumcraft:swing",1,1);return true;}
    @Override public UseAnim getUseAnimation(ItemStack s){return UseAnim.BOW;}@Override public int getUseDuration(ItemStack s){return 72000;}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand hand){var s=p.getItemInHand(hand);if(s.hasTag()&&s.getTag().getInt("cooldown")>0)return InteractionResultHolder.fail(s);p.startUsingItem(hand);return InteractionResultHolder.consume(s);}
    @Override public void onUseTick(Level l,LivingEntity owner,ItemStack s,int remaining){if(!l.isClientSide&&owner.tickCount%5==0)TMRuntime.sound(l,owner.blockPosition(),"thaumcraft:wind",.1f,.9f);}
    @Override public void releaseUsing(ItemStack s,Level l,LivingEntity owner,int remaining){if(l.isClientSide||!(owner instanceof Player p)||getUseDuration(s)-remaining<20)return;boolean inscribed=s.hasTag()&&s.getTag().contains("inscription");if(!inscribed||p.isShiftKeyDown()){var target=tc4revival.content.FocusTargeting.pointed(p,0,p.getEntityReach(),0,e->e instanceof LivingEntity);if(target instanceof LivingEntity living&&(!(living instanceof Player other)||p.canHarmPlayer(other))){float multiplier=1.5f+(l.random.nextInt(10)==0?1:0);living.hurt(chargedSource(p),damage()*multiplier);}TMRuntime.sound(l,p.blockPosition(),"thaumcraft:swing",1,1);}else{switch(s.getTag().getInt("inscription")){case 0->{var orb=new tc4revival.content.ExplosiveOrbEntity(l,p,damage()*.25f,false);l.addFreshEntity(orb);}case 1->MagicFocus.shockwave(p,10,damage()*.25f,5,1.5,false);case 2->{p.heal((p.getMaxHealth()-p.getHealth())*.5f);for(var e:l.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(5)))if(e!=p)e.addEffect(new MobEffectInstance(MobEffects.WITHER,100,1));p.addEffect(new MobEffectInstance(MobEffects.REGENERATION,60,1));p.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,120,1));TMEffects.healing(l,p.position().add(0,1,0));TMRuntime.sound(l,p.blockPosition(),"thaumcraft:wand",1,1);}}s.getOrCreateTag().putInt("cooldown",140);}p.swing(p.getUsedItemHand(),true);}
    @Override public void inventoryTick(ItemStack s,Level l,Entity e,int slot,boolean held){if(s.hasTag()&&s.getTag().getInt("cooldown")>0)s.getTag().putInt("cooldown",s.getTag().getInt("cooldown")-1);}
    @Override public void appendHoverText(ItemStack s,Level l,java.util.List<Component> lines,TooltipFlag f){if(material>0)lines.add(Component.translatable(material==1?"enchantment.special.sapless":"enchantment.special.sapgreat"));if(s.hasTag()&&s.getTag().contains("inscription"))lines.add(Component.translatable("text.katana.inscription."+s.getTag().getInt("inscription")));}
    @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new TMClient.ItemExtension());}
}
